import{_ as p,a0 as l,w as o,s as d,ao as r,I as i,x as a,a1 as n,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const m=JSON.parse('{"title":"PHP PDO 簡單教程 | LCTT x X-CMD","titleTemplate":false,"description":"PHP PDO 簡單教程 | LCTT (201905) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"PHP PDO 簡單教程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"PHP PDO 簡單教程 | LCTT (201905) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201905/20180429 The Easiest PDO Tutorial (Basics)","title":"PHP PDO 簡單教程","tag":"201905","desc":""},"relativePath":"201905/20180429 The Easiest PDO Tutorial (Basics).md","filePath":"[post].md"}'),h={name:"201905/20180429 The Easiest PDO Tutorial (Basics).md"};function c(g,s,u,b,k,P){const e=l("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="php-pdo-簡單教程" tabindex="-1">PHP PDO 簡單教程 <a class="header-anchor" href="#php-pdo-簡單教程" aria-label="Permalink to “PHP PDO 簡單教程”">​</a></h1><p><img src="http://www.theitstuff.com/wp-content/uploads/2018/04/php-language.jpg" alt=""></p><p>大約 80% 的 Web 應用程序由 PHP 提供支持。類似地，SQL 也是如此。PHP 5.5 版本之前，我們有用於訪問 MySQL 資料庫的 mysql_ 命令，但由於安全性不足，它們最終被棄用。</p><p>棄用這件事是發生在 2013 年的 PHP 5.5 上，我寫這篇文章的時間是 2018 年，PHP 版本為 7.2。mysql_ 的棄用帶來了訪問資料庫的兩種主要方法：mysqli 和 PDO 庫。</p><p>雖然 mysqli 庫是官方指定的，但由於 mysqli 只能支持 mysql 資料庫，而 PDO 可以支持 12 種不同類型的資料庫驅動程序，因此 PDO 獲得了更多的讚譽。此外，PDO 還有其它一些特性，使其成為大多數開發人員的更好選擇。你可以在下表中看到一些特性比較：</p><div class="table-wrap"><table><thead><tr><th></th><th>PDO</th><th>MySQLi</th></tr></thead><tbody><tr><td>資料庫支持</td><td>12 種驅動</td><td>只有 MySQL</td></tr><tr><td>範例</td><td>OOP</td><td>過程 + OOP</td></tr><tr><td>預處理語句（客户端側）</td><td>Yes</td><td>No</td></tr><tr><td>1命名參數</td><td>Yes</td><td>No</td></tr></tbody></table></div><p>現在我想對於大多數開發人員來説，PDO 是首選的原因已經很清楚了。所以讓我們深入研究它，並希望在本文中儘量涵蓋關於 PDO 你需要的瞭解的。</p><h3 id="連接" tabindex="-1">連接 <a class="header-anchor" href="#連接" aria-label="Permalink to “連接”">​</a></h3><p>第一步是連接到資料庫，由於 PDO 是完全面向對象的，所以我們將使用 PDO 類的實例。</p><p>我們要做的第一件事是定義主機、資料庫名稱、用户名、密碼和資料庫字符集。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$host = &#39;localhost&#39;;</span></span>
<span class="line"><span>$db   = &#39;theitstuff&#39;;</span></span>
<span class="line"><span>$user = &#39;root&#39;;</span></span>
<span class="line"><span>$pass = &#39;root&#39;;</span></span>
<span class="line"><span>$charset = &#39;utf8mb4&#39;;</span></span>
<span class="line"><span>$dsn = &quot;mysql:host=$host;dbname=$db;charset=$charset&quot;;</span></span>
<span class="line"><span>$conn = new PDO($dsn, $user, $pass);</span></span></code></pre></div><p>之後，正如你在上面的代碼中看到的，我們創建了 DSN 變量，DSN 變量只是一個保存資料庫信息的變量。對於一些在外部服務器上運行 MySQL 的人，你還可以通過提供一個 <code>port=$port_number</code> 來調整端口號。</p><p>最後，你可以創建一個 PDO 類的實例，我使用了 <code>$conn</code> 變量，並提供了 <code>$dsn</code>、<code>$user</code>、<code>$pass</code> 參數。如果你遵循這些步驟，你現在應該有一個名為 <code>$conn</code> 的對象，它是 PDO 連接類的一個實例。現在是時候進入資料庫並運行一些查詢。</p><h3 id="一個簡單的-sql-查詢" tabindex="-1">一個簡單的 SQL 查詢 <a class="header-anchor" href="#一個簡單的-sql-查詢" aria-label="Permalink to “一個簡單的 SQL 查詢”">​</a></h3><p>現在讓我們運行一個簡單的 SQL 查詢。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$tis = $conn-&gt;query(&#39;SELECT name, age FROM students&#39;);</span></span>
<span class="line"><span>while ($row = $tis-&gt;fetch())</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  echo $row[&#39;name&#39;].&quot;\\t&quot;;</span></span>
<span class="line"><span>  echo $row[&#39;age&#39;];</span></span>
<span class="line"><span>  echo &quot;&lt;br&gt;&quot;;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>這是使用 PDO 運行查詢的最簡單形式。我們首先創建了一個名為 <code>tis</code>（TheITStuff 的縮寫 ）的變量，然後你可以看到我們使用了創建的 <code>$conn</code> 對象中的查詢函數。</p><p>然後我們運行一個 <code>while</code> 循環並創建了一個 <code>$row</code> 變量來從 <code>$tis</code> 對象中獲取內容，最後通過調用列名來顯示每一行。</p><p>很簡單，不是嗎？現在讓我們來看看預處理語句。</p><h3 id="預處理語句" tabindex="-1">預處理語句 <a class="header-anchor" href="#預處理語句" aria-label="Permalink to “預處理語句”">​</a></h3><p>預處理語句是人們開始使用 PDO 的主要原因之一，因為它提供了可以阻止 SQL 注入的語句。</p><p>有兩種基本方法可供使用，你可以使用位置參數或命名參數。</p><h4 id="位置參數" tabindex="-1">位置參數 <a class="header-anchor" href="#位置參數" aria-label="Permalink to “位置參數”">​</a></h4><p>讓我們看一個使用位置參數的查詢示例。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$tis = $conn-&gt;prepare(&quot;INSERT INTO STUDENTS(name, age) values(?, ?)&quot;);</span></span>
<span class="line"><span>$tis-&gt;bindValue(1,&#39;mike&#39;);</span></span>
<span class="line"><span>$tis-&gt;bindValue(2,22);</span></span>
<span class="line"><span>$tis-&gt;execute();</span></span></code></pre></div><p>在上面的例子中，我們放置了兩個問號，然後使用 <code>bindValue()</code> 函數將值映射到查詢中。這些值綁定到語句問號中的位置。</p><p>我還可以使用變量而不是直接提供值，通過使用 <code>bindParam()</code> 函數相同例子如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$name=&#39;Rishabh&#39;; $age=20;</span></span>
<span class="line"><span>$tis = $conn-&gt;prepare(&quot;INSERT INTO STUDENTS(name, age) values(?, ?)&quot;);</span></span>
<span class="line"><span>$tis-&gt;bindParam(1,$name);</span></span>
<span class="line"><span>$tis-&gt;bindParam(2,$age);</span></span>
<span class="line"><span>$tis-&gt;execute();</span></span></code></pre></div><h3 id="命名參數" tabindex="-1">命名參數 <a class="header-anchor" href="#命名參數" aria-label="Permalink to “命名參數”">​</a></h3><p>命名參數也是預處理語句，它將值/變量映射到查詢中的命名位置。由於沒有位置綁定，因此在多次使用相同變量的查詢中非常有效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$name=&#39;Rishabh&#39;; $age=20;</span></span>
<span class="line"><span>$tis = $conn-&gt;prepare(&quot;INSERT INTO STUDENTS(name, age) values(:name, :age)&quot;);</span></span>
<span class="line"><span>$tis-&gt;bindParam(&#39;:name&#39;, $name);</span></span>
<span class="line"><span>$tis-&gt;bindParam(&#39;:age&#39;, $age);</span></span>
<span class="line"><span>$tis-&gt;execute();</span></span></code></pre></div><p>你可以注意到，唯一的變化是我使用 <code>:name</code> 和 <code>:age</code> 作為佔位符，然後將變量映射到它們。冒號在參數之前使用，讓 PDO 知道該位置是一個變量，這非常重要。</p><p>你也可以類似地使用 <code>bindValue()</code> 來使用命名參數直接映射值。</p><h3 id="獲取數據" tabindex="-1">獲取數據 <a class="header-anchor" href="#獲取數據" aria-label="Permalink to “獲取數據”">​</a></h3><p>PDO 在獲取數據時非常豐富，它實際上提供了許多格式來從資料庫中獲取數據。</p><p>你可以使用 <code>PDO::FETCH_ASSOC</code> 來獲取關聯數組，<code>PDO::FETCH_NUM</code> 來獲取數字數組，使用 <code>PDO::FETCH_OBJ</code> 來獲取對象數組。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$tis = $conn-&gt;prepare(&quot;SELECT * FROM STUDENTS&quot;);</span></span>
<span class="line"><span>$tis-&gt;execute();</span></span>
<span class="line"><span>$result = $tis-&gt;fetchAll(PDO::FETCH_ASSOC);</span></span></code></pre></div><p>你可以看到我使用了 <code>fetchAll</code>，因為我想要所有匹配的記錄。如果只需要一行，你可以簡單地使用 <code>fetch</code>。</p><p>現在我們已經獲取了數據，現在是時候循環它了，這非常簡單。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>foreach ($result as $lnu){</span></span>
<span class="line"><span>  echo $lnu[&#39;name&#39;];</span></span>
<span class="line"><span>  echo $lnu[&#39;age&#39;].&quot;&lt;br&gt;&quot;;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>你可以看到，因為我請求了關聯數組，所以我正在按名稱訪問各個成員。</p><p>雖然在定義希望如何傳輸遞數據方面沒有要求，但在定義 <code>$conn</code> 變量本身時，實際上可以將其設置為默認值。</p><p>你需要做的就是創建一個 <code>$options</code> 數組，你可以在其中放入所有默認配置，只需在 <code>$conn</code> 變量中傳遞數組即可。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$options = [</span></span>
<span class="line"><span>  PDO::ATTR_DEFAULT_FETCH_MODE =&gt; PDO::FETCH_ASSOC,</span></span>
<span class="line"><span>];</span></span>
<span class="line"><span>$conn = new PDO($dsn, $user, $pass, $options);</span></span></code></pre></div><p>這是一個非常簡短和快速的 PDO 介紹，我們很快就會製作一個高級教程。如果你在理解本教程的任何部分時遇到任何困難，請在評論部分告訴我，我會在那你為你解答。</p><hr>`,46)),i("p",null,[s[1]||(s[1]=a("via: ",-1)),n(e,{href:"http://www.theitstuff.com/easiest-pdo-tutorial-basics"},{default:t(()=>[...s[0]||(s[0]=[a("http://www.theitstuff.com/easiest-pdo-tutorial-basics",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=a("作者：",-1)),n(e,{href:"http://www.theitstuff.com/author/reevkandari"},{default:t(()=>[...s[2]||(s[2]=[a("Rishabh Kandari",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),n(e,{href:"https://github.com/MjSeven"},{default:t(()=>[...s[4]||(s[4]=[a("MjSeven",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const T=p(h,[["render",c]]);export{m as __pageData,T as default};
